parameters.jsCode:
const ESCALATION_THRESHOLD = 6; // Change this to tune sensitivity
const raw = $input.first().json.content[0].text;
let analysis;
try {
  analysis = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { analysis = JSON.parse(m[0]); } catch { analysis = { escalation_score: 5, should_escalate: false, anger_level: 3, churn_risk: 'medium', signals_detected: [], recommended_action: 'Review manually', manager_briefing: raw.substring(0, 200), suggested_agent_response: '' }; }
}

const input = $('Extract Message').first().json;
const forceEscalate = input.previous_contacts >= 3 || analysis.escalation_score >= ESCALATION_THRESHOLD;

return [{ json: {
  ...analysis,
  should_escalate: forceEscalate,
  customer_name: input.customer_name,
  ticket_id: input.ticket_id,
  channel: input.channel,
  previous_contacts: input.previous_contacts,
  timestamp: new Date().toISOString()
}}];

